        "minLength": 1
      },
      "confidence": {
        "type": "number",
        "minimum": 0,
        "maximum": 1
      },
      "assumptions": {
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    },
    "required": [
      "outcome",
      "edits",
      "rationale",
      "confidence",
      "assumptions"
    ]
  }
}
